      "claim": "Benazepril, an ester prodrug ACE inhibitor, has oral bioavailability of 28–37% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Delapril, an ester prodrug ACE inhibitor, has oral bioavailability >55% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphinate ester prodrug ACE inhibitor (fosinopril-like). Multiple structurally related ACE inhibitor prodrugs—quinapril, perindopril, moexipril, benazepril, delapril, and pentopril—show absolute oral bioavailability values of 22–75%, all above the 20% threshold. The closest analogue, a phosphonate ACE inhibitor, has 66% oral bioavailability. Therefore high oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct fosinopril bioavailability record is present in the supplied evidence; prediction relies on close analogues.",
    "Some records report active metabolite exposure rather than parent prodrug F, but the consistent high-F pattern among prodrugs is clear."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

